package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase._serializeAsString
 */
public class DateTimeSerializerBase__serializeAsString_TriageGen0Test {

    private JsonGenerator g;
    private SerializerProvider provider;
    private Date testDate;

    // Concrete implementation of the abstract class for testing purposes
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Object> {
        protected TestDateTimeSerializer(Class<Object> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Object value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            _serializeAsString(value != null ? (Date) value : null, gen, serializers);
        }

        @Override
        protected long _timestamp(Object value) {
            return 0L;
        }

        @Override
        public JsonSerializer<?> createContextual(SerializerProvider serializers, com.fasterxml.jackson.databind.BeanProperty property) {
            return this;
        }

        @Override
        public JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) {
        }
    }

    @Before
    public void setUp() {
        g = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
        testDate = new Date(1234567890L); // Fixed date for testing
    }

    @Test
    public void testSerializeAsString_NoCustomFormat() throws IOException {
        // Case: _customFormat is null -> should call provider.defaultSerializeDateValue
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, null);

        serializer._serializeAsString(testDate, g, provider);

        verify(provider, times(1)).defaultSerializeDateValue(testDate, g);
        verify(g, never()).writeString(anyString());
    }

    @Test
    public void testSerializeAsString_WithCustomFormat_ReusesFormat() throws IOException {
        // Case: _customFormat is provided. 
        // First call: _reusedCustomFormat.getAndSet(null) returns null -> clones.
        // Second call: _reusedCustomFormat.getAndSet(null) returns existing -> reuses.

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, sdf);
        String expectedOutput = sdf.format(testDate);

        // First pass: triggers clone
        serializer._serializeAsString(testDate, g, provider);
        verify(g).writeString(expectedOutput);

        // Second pass: triggers reuse (no clone call implicitly via logic, but we check if it writes correctly)
        // Note: we can't easily verify "clone" call on standard DateFormat, but we verify the result.
        reset(g);
        serializer._serializeAsString(testDate, g, provider);
        verify(g).writeString(expectedOutput);
    }

    @Test
    public void testSerializeAsString_WithCustomFormat_CloningMechanism() throws IOException {
        // To ensure we hit the clone branch specifically
        // We simulate a scenario where the internal ThreadLocal (reusedCustomFormat) is empty

        DateFormat customFormat = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, customFormat);

        // The first call will always enter the (f == null) block because the ThreadLocal is initially empty.
        serializer._serializeAsString(testDate, g, provider);

        verify(g).writeString(customFormat.format(testDate));
        verify(provider, never()).defaultSerializeDateValue(any(), any());
    }

    @Test(expected = IOException.class)
    public void testSerializeAsString_ThrowsIOException() throws IOException {
        // Case: JsonGenerator throws exception
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Object.class, false, sdf);

        doThrow(new IOException("Simulated error")).when(g).writeString(anyString());

        serializer._serializeAsString(testDate, g, provider);
    }
}
